def is_sorted(lst):
    import collections
    if len(lst) == 0:
        return True
    for i in range(len(lst)-1):
        if lst[i] > lst[i+1]:
            return False
    counts = collections.Counter(lst)
    for c in counts.values():
        if c > 1:
            return False
    return True
